import java.util.*;

public class Main {
    int removeElement(int[] nums, int val) {
        List<Integer> survivors = new ArrayList<>();                    // builds a completely separate array
        for (int num : nums) {
            if (num != val) survivors.add(num);
        }
        for (int i = 0; i < survivors.size(); i++) nums[i] = survivors.get(i);
        return survivors.size();
    }

    public static void main(String[] args) {
        int[] nums = {3, 2, 2, 3};
        Main solution = new Main();
        int k = solution.removeElement(nums, 3);
        System.out.println(k + " " + Arrays.toString(Arrays.copyOfRange(nums, 0, k)));
    }
}

