#include <bits/stdc++.h>
using namespace std;

int removeElement(vector<int>& nums, int val) {
    vector<int> survivors;                                             // builds a completely separate array
    for (int num : nums) {
        if (num != val) survivors.push_back(num);
    }
    for (int i = 0; i < (int)survivors.size(); i++) nums[i] = survivors[i];
    return (int)survivors.size();
}

int main() {
    vector<int> nums = {3, 2, 2, 3};
    int k = removeElement(nums, 3);
    cout << k << " ";
    for (int i = 0; i < k; i++) cout << nums[i] << " ";
    cout << endl;
    return 0;
}

