def remove_element(nums, val):
    n = len(nums)
    i = 0
    while i < n:
        if nums[i] == val:
            nums[i] = nums[n - 1]                                 # swap in the last element instead of shifting
            n -= 1                                                    # shrink the considered range by one
        else:
            i += 1
    return n


if __name__ == "__main__":
    nums = [0, 1, 2, 2, 3]
    k = remove_element(nums, 2)
