public class Main {
    int removeElement(int[] nums, int val) {
        int n = nums.length;
        int i = 0;
        while (i < n) {
            if (nums[i] == val) {
                nums[i] = nums[n - 1];                                     // swap in the last element instead of shifting
                n--;                                                          // shrink the considered range by one
            } else {
                i++;
            }
        }
        return n;
    }

